<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {useRestaurant} from '../store';import {balance,canPay,money,amountToCents,orderTotal} from '../domain';
const s=useRestaurant(),selected=ref(''),method=ref<'Cash'|'Card'>('Cash'),amount=ref(''),received=ref('');
const sessions=computed(()=>s.state.sessions.filter(x=>!x.closed&&(s.role!=='Waiter'||x.waiter===s.waiter)));
const session=computed(()=>s.state.sessions.find(x=>x.id===selected.value&&(s.role!=='Waiter'||x.waiter===s.waiter)));
const orders=computed(()=>s.state.orders.filter(o=>o.sessionId===selected.value));
const due=computed(()=>session.value?balance(s.state,session.value.id):0);
const change=computed(()=>{try{return Math.max(0,amountToCents(received.value)-amountToCents(amount.value))}catch{return 0}});
watch(selected,()=>{amount.value=(due.value/100).toFixed(2);received.value='';});
function pay(){s.act(()=>{s.pay(selected.value,amountToCents(amount.value),method.value==='Cash'?amountToCents(received.value):amountToCents(amount.value),method.value);amount.value=(due.value/100).toFixed(2);received.value='';});}
</script><template><div class="page-heading"><div><p class="eyebrow">CUENTAS CLARAS</p><h1>Caja y cobros</h1><p class="muted">Pagos parciales, efectivo o tarjeta. Sin perder un detalle.</p></div></div><div class="payment-layout"><section class="panel"><div class="panel-heading"><h2>Cuentas abiertas</h2><span class="count">{{sessions.length}}</span></div><div v-if="!sessions.length" class="empty">No hay cuentas abiertas.</div><button v-for="x in sessions" class="account-row" :class="{selected:selected===x.id}" @click="selected=x.id"><span><strong>{{s.state.tables.find(t=>t.id===x.tableId)?.code}}</strong><small>{{x.waiter}}</small></span><b>{{money(balance(s.state,x.id))}} →</b></button></section><section class="panel payment-detail"><template v-if="session"><div class="panel-heading"><h2>Cuenta · {{s.state.tables.find(t=>t.id===session!.tableId)?.code}}</h2><span class="pill Delivered" v-if="session.closed">Pagada</span></div><div class="detail-content"><div class="receipt"><div v-for="o in orders" class="receipt-order"><div v-for="(line,i) in o.lines" :key="i" class="inline" :class="{muted:o.status==='Cancelled'}"><span>{{line.quantity}} × {{line.name}}{{o.status==='Cancelled'?' (cancelado)':''}}</span><b>{{money(o.status==='Cancelled'?0:line.price*line.quantity)}}</b></div></div><div class="inline subtotal"><span>Total</span><strong>{{money(orders.reduce((sum,o)=>sum+orderTotal(o),0))}}</strong></div><div v-for="p in session.payments" class="payment-record"><div class="inline"><span>{{p.method==='Cash'?'Efectivo':'Tarjeta'}} · pago registrado</span><b>−{{money(p.amount)}}</b></div><small v-if="p.method==='Cash'">Recibido {{money(p.received)}} · Vuelto {{money(p.change)}}</small></div><div class="balance-line"><span>Saldo pendiente</span><strong>{{money(due)}}</strong></div></div><p v-if="!canPay(s.state,session.id)" class="alert">Hay pedidos pendientes de entrega. Completá el servicio antes de cobrar.</p><form v-if="!session.closed&&s.canCharge&&canPay(s.state,session.id)&&due>0" @submit.prevent="pay"><h3>Registrar pago</h3><div class="tabs"><button type="button" :class="{active:method==='Cash'}" @click="method='Cash'">Efectivo</button><button type="button" :class="{active:method==='Card'}" @click="method='Card'">Tarjeta</button></div><label>Importe a aplicar (Q)<input v-model="amount" inputmode="decimal" required/></label><label v-if="method==='Cash'">Efectivo recibido (Q)<input v-model="received" inputmode="decimal" required/></label><div v-if="method==='Cash'" class="inline change"><span>Vuelto</span><strong>{{money(change)}}</strong></div><p class="muted">El pago se registra manualmente. No se procesan tarjetas.</p><button class="primary wide">Registrar pago</button></form><button v-if="!session.closed&&s.canCharge&&due===0&&canPay(s.state,session.id)" class="primary wide" @click="s.act(()=>s.close(session!.id))">Cerrar cuenta y liberar mesa</button><p v-if="session.closed" class="success alert">Cuenta completada. La mesa ya está libre.</p><p class="receipt-note">Comprobante de consumo interno · Control de cuenta</p></div></template><div v-else class="empty-detail"><span>▤</span><h2>Seleccioná una cuenta</h2><p>Acá verás el desglose y los pagos de la mesa.</p></div></section></div></template>